import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

# ── Setup ────────────────────────────────────────────────────────────────────
df_c = df[df['row_kind'] == 'counted'].copy()
df_c['Admit Date'] = pd.to_datetime(df_c['Admit Date'], errors='coerce')
df_c['Discharge Date'] = pd.to_datetime(df_c['Discharge Date'], errors='coerce')

# LOS as a local series only — never stored as a column name in result
los = (df_c['Discharge Date'] - df_c['Admit Date']).dt.days

ip_mask = df_c['Encounter Type'].str.lower().str.strip().isin(['inpatient', 'ip', 'inpt', 'i'])
excl_disp = {20, 7, 2, 82}   # numeric codes for death/AMA/transfer

# ── EDA ──────────────────────────────────────────────────────────────────────
try:
    tc = df_c['Total Charges'].dropna()
    result['eda_summary']['Total Charges'] = {
        'mean': round(float(tc.mean()), 2), 'std': round(float(tc.std()), 2),
        'min': round(float(tc.min()), 2),  'max': round(float(tc.max()), 2),
        'median': round(float(tc.median()), 2), 'count': int(tc.count())
    }
    los_valid = los.dropna()
    result['eda_summary']['Discharge Date'] = {
        'mean': round(float(los_valid.mean()), 3), 'std': round(float(los_valid.std()), 3),
        'min': float(los_valid.min()), 'max': float(los_valid.max()),
        'median': float(los_valid.median()), 'count': int(los_valid.count())
    }
except Exception:
    pass

# ── CORRELATIONS ─────────────────────────────────────────────────────────────
try:
    los_aligned = los.reindex(df_c.index)
    tc_aligned = df_c['Total Charges']
    both = pd.concat([tc_aligned, los_aligned], axis=1).dropna()
    both.columns = ['tc', 'los']
    r = float(both['tc'].corr(both['los']))
    if abs(r) >= 0.2:
        result['correlations']['Total Charges__Discharge Date'] = round(r, 4)
except Exception:
    pass

# ── SEGMENTATION ─────────────────────────────────────────────────────────────
try:
    # Mean Total Charges by each segment column
    for sc in ['Encounter Type', 'Department', 'Discharge Disposition']:
        grp = df_c.groupby(sc)['Total Charges'].mean().nlargest(10)
        result['segments'].append({
            'segment_column': sc, 'metric_column': 'Total Charges',
            'aggregation': 'mean', 'label': None,
            'results': [{'name': str(k), 'value': round(float(v), 2)} for k, v in grp.items()]
        })

    # Encounter counts by segment
    for sc in ['Encounter Type', 'Department']:
        grp = df_c.groupby(sc)['Encounter ID'].count().nlargest(10)
        result['segments'].append({
            'segment_column': sc, 'metric_column': 'Encounter ID',
            'aggregation': 'count', 'label': None,
            'results': [{'name': str(k), 'value': int(v)} for k, v in grp.items()]
        })

    # ALOS by Department (inpatient only, discharge date present)
    ip_df = df_c[ip_mask & df_c['Discharge Date'].notna()].copy()
    ip_df_los = los.reindex(ip_df.index)
    if len(ip_df) >= 30:
        alos_grp = ip_df.groupby('Department').apply(
            lambda x: ip_df_los.reindex(x.index).sum() / x['Encounter ID'].nunique()
        ).nlargest(10)
        result['segments'].append({
            'segment_column': 'Department', 'metric_column': 'Discharge Date',
            'aggregation': 'mean', 'label': 'alos_by_department',
            'results': [{'name': str(k), 'value': round(float(v), 3)} for k, v in alos_grp.items()]
        })

    # 30-day readmission rate
    ip_disch = df_c[ip_mask & df_c['Discharge Date'].notna()].copy()
    ip_disch['disp_int'] = pd.to_numeric(ip_disch['Discharge Disposition'], errors='coerce')
    ip_elig = ip_disch[~ip_disch['disp_int'].isin(excl_disp)].copy()
    last_admit = df_c['Admit Date'].max()
    cutoff = last_admit - pd.Timedelta(days=30)
    denom_df = ip_elig[ip_elig['Discharge Date'] <= cutoff].copy()
    ip_admits = df_c[ip_mask][['MRN', 'Admit Date']].dropna()
    readmit_count = 0
    for _, row in denom_df.iterrows():
        pat, disch_dt = row['MRN'], row['Discharge Date']
        future = ip_admits[
            (ip_admits['MRN'] == pat) &
            (ip_admits['Admit Date'] > disch_dt) &
            (ip_admits['Admit Date'] <= disch_dt + pd.Timedelta(days=30))
        ]
        if len(future) > 0:
            readmit_count += 1
    denom_n = len(denom_df)
    readmit_rate = readmit_count / denom_n if denom_n > 0 else float('nan')
    result['segments'].append({
        'segment_column': 'Encounter Type', 'metric_column': 'Admit Date',
        'aggregation': 'ratio', 'label': 'readmission_rate_30d',
        'results': [{'name': 'Inpatient', 'value': round(float(readmit_rate), 4)}]
    })

    # In-hospital mortality rate
    mort_codes = {20}
    ip_disch['is_mort'] = ip_disch['disp_int'].isin(mort_codes)
    n_enc = ip_disch['Encounter ID'].nunique()
    mort_rate = ip_disch['is_mort'].sum() / n_enc if n_enc > 0 else float('nan')
    result['segments'].append({
        'segment_column': 'Encounter Type', 'metric_column': 'Discharge Disposition',
        'aggregation': 'ratio', 'label': 'mortality_rate',
        'results': [{'name': 'Inpatient', 'value': round(float(mort_rate), 4)}]
    })
except Exception:
    pass

# ── ANOMALIES ─────────────────────────────────────────────────────────────────
try:
    all_anomalies = []
    tc = df_c['Total Charges'].dropna()
    skew_tc = float(tc.skew())
    shift = max(0, -tc.min() + 1)
    tc_t = np.log1p(tc + shift) if abs(skew_tc) > 2 else tc
    q1, q3 = float(tc_t.quantile(0.25)), float(tc_t.quantile(0.75))
    iqr = q3 - q1
    lo_t, hi_t = q1 - 3 * iqr, q3 + 3 * iqr
    lo_orig = float(np.expm1(lo_t) - shift) if abs(skew_tc) > 2 else lo_t
    hi_orig = float(np.expm1(hi_t) - shift) if abs(skew_tc) > 2 else hi_t
    mask_ext = (tc_t < lo_t) | (tc_t > hi_t)
    pct_flagged = mask_ext.sum() / len(tc)
    if pct_flagged > 0.05:
        all_anomalies.append({
            'column': 'Total Charges', 'row_index': None, 'value': None,
            'expected_range': f'{lo_orig:.2f} to {hi_orig:.2f}',
            'severity': 'low',
            'explanation': 'Total Charges is heavy-tailed; more than 5% of values fall outside the extreme IQR boundary'
        })
    else:
        for idx in tc[mask_ext].index[:25]:
            val = float(df_c.loc[idx, 'Total Charges'])
            vt = float(tc_t.loc[idx])
            if vt > q3 + 5 * iqr or vt < q1 - 5 * iqr:
                sev = 'critical'
            elif vt > q3 + 4 * iqr or vt < q1 - 4 * iqr:
                sev = 'high'
            else:
                sev = 'medium'
            all_anomalies.append({
                'column': 'Total Charges', 'row_index': int(idx), 'value': round(val, 2),
                'expected_range': f'{lo_orig:.2f} to {hi_orig:.2f}',
                'severity': sev,
                'explanation': f'Total Charges value {val:.2f} lies outside expected range {lo_orig:.2f} to {hi_orig:.2f}'
            })
    result['anomalies'] = all_anomalies[:25]
except Exception:
    pass

# ── TRENDS ────────────────────────────────────────────────────────────────────
try:
    df_c['_month'] = df_c['Discharge Date'].dt.to_period('M')

    # Mean Total Charges MoM
    monthly_tc = df_c.groupby('_month')['Total Charges'].mean().sort_index()
    if len(monthly_tc) >= 2:
        pct = float((monthly_tc.iloc[-1] - monthly_tc.iloc[-2]) / monthly_tc.iloc[-2] * 100)
        result['trends'].append({
            'column': 'Total Charges', 'period': 'MoM',
            'direction': 'up' if pct > 1 else ('down' if pct < -1 else 'flat'),
            'pct_change': round(pct, 2), 'segment': None
        })

    # Discharge volume MoM
    monthly_vol = df_c.groupby('_month')['Encounter ID'].count().sort_index()
    if len(monthly_vol) >= 2:
        pct_v = float((monthly_vol.iloc[-1] - monthly_vol.iloc[-2]) / monthly_vol.iloc[-2] * 100)
        result['trends'].append({
            'column': 'Encounter ID', 'period': 'MoM',
            'direction': 'up' if pct_v > 1 else ('down' if pct_v < -1 else 'flat'),
            'pct_change': round(pct_v, 2), 'segment': None
        })

    # ALOS (mean LOS) MoM — inpatient only
    ip_m = df_c[ip_mask & df_c['Discharge Date'].notna()].copy()
    ip_m_los = los.reindex(ip_m.index)
    ip_m['_los'] = ip_m_los.values
    monthly_los = ip_m.groupby('_month')['_los'].mean().sort_index()
    if len(monthly_los) >= 2:
        pct_l = float((monthly_los.iloc[-1] - monthly_los.iloc[-2]) / monthly_los.iloc[-2] * 100)
        result['trends'].append({
            'column': 'Discharge Date', 'period': 'MoM',
            'direction': 'up' if pct_l > 1 else ('down' if pct_l < -1 else 'flat'),
            'pct_change': round(pct_l, 2), 'segment': 'Inpatient'
        })
except Exception:
    pass

# ── FORECASTING ───────────────────────────────────────────────────────────────
try:
    monthly_tc2 = df_c.groupby('_month')['Total Charges'].mean().sort_index()
    if len(monthly_tc2) >= 3:
        x = np.arange(len(monthly_tc2), dtype=float)
        y = monthly_tc2.values.astype(float)
        coeffs = np.polyfit(x, y, 1)
        nx1, nx2 = float(len(monthly_tc2)), float(len(monthly_tc2) + 1)
        v1 = round(float(np.polyval(coeffs, nx1)), 2)
        v2 = round(float(np.polyval(coeffs, nx2)), 2)
        p1 = (monthly_tc2.index[-1] + 1).strftime('%Y-%m')
        p2 = (monthly_tc2.index[-1] + 2).strftime('%Y-%m')
        result['forecast_points'].append({'period': p1, 'value': v1})
        result['forecast_points'].append({'period': p2, 'value': v2})
except Exception:
    pass

# ── ASSUMPTIONS ───────────────────────────────────────────────────────────────
result['assumptions'] = [
    "Only 'counted' rows used; test/voided/superseded rows excluded.",
    "LOS = Discharge Date minus Admit Date in whole days; EDA for LOS stored under 'Discharge Date' key.",
    "ALOS and readmission rate restricted to Encounter Type == 'Inpatient' with a valid Discharge Date.",
    "30-day readmission excludes disposition codes 20/7/2/82 (death, AMA, transfer); last-30-day discharges excluded from denominator.",
    "Forecast uses linear extrapolation on monthly mean Total Charges — directional guidance only."
]

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
    _miss = df.isna().mean() * 100
    result['missing_pct'] = {str(k): round(float(v), 2) for k, v in _miss.items()}
except Exception:
    pass

try:
    if 'Total Charges' in df.columns and pd.api.types.is_numeric_dtype(df['Total Charges']):
        _s = df['Total Charges'].dropna()
        if len(_s) > 0 and 'Total Charges' not in result['eda_summary']:
            result['eda_summary']['Total Charges'] = {
                'mean': round(float(_s.mean()), 4),
                'std': round(float(_s.std()), 4),
                'min': round(float(_s.min()), 4),
                'max': round(float(_s.max()), 4),
                'median': round(float(_s.median()), 4),
                'count': int(_s.count()),
            }
except Exception:
    pass

try:
    if 'Total Charges' in df.columns and pd.api.types.is_numeric_dtype(df['Total Charges']):
        _col_data = df['Total Charges'].dropna()
        if len(_col_data) >= 5:
            _n_bins = min(10, max(2, _col_data.nunique()))
