try:
    if 'Patient ZIP' in df.columns:
        _vc = df['Patient ZIP'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['Patient ZIP'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
    pass

try:
    if 'Encounter Type' in df.columns:
        _vc = df['Encounter Type'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['Encounter Type'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
